<?php require_once '../../includes/functions.php'; requireLogin(); global $pdo; $status = $_GET['status'] ?? 'all'; $sql = "SELECT q.*, c.name as customer_name FROM erp_quotes q JOIN erp_customers c ON q.customer_id = c.id WHERE 1=1"; $params = []; if ($status !== 'all') { $sql .= " AND q.status = ?"; $params[] = $status; } $sql .= " ORDER BY q.date DESC"; $stmt = $pdo->prepare($sql); $stmt->execute($params); $quotes = $stmt->fetchAll(); ?>
<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Quotes - ERP</title><link rel="stylesheet" href="../../assets/css/style.css?v=<?= time() ?>"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { background: #f5f5f5; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif; } .header { background: #fff; border-bottom: 1px solid #e0e0e0; padding: 16px 24px; display: flex; justify-content: space-between; align-items: center; } .header h1 { font-size: 1.5rem; font-weight: 500; } .container { max-width: 1400px; margin: 0 auto; padding: 24px; } .card { background: white; border-radius: 8px; border: 1px solid #e0e0e0; overflow: hidden; } .card-header { padding: 20px 24px; border-bottom: 1px solid #e0e0e0; } .filters { display: flex; gap: 12px; } .filter-select { padding: 10px 16px; border: 1px solid #dadce0; border-radius: 4px; font-size: 0.875rem; background: white; } .table { width: 100%; border-collapse: collapse; } .table th { text-align: left; padding: 12px 16px; font-size: 0.75rem; font-weight: 500; color: #5f6368; text-transform: uppercase; border-bottom: 1px solid #e0e0e0; background: #f8f9fa; } .table td { padding: 16px; border-bottom: 1px solid #f1f3f4; } .table tr:hover { background: #f8f9fa; } .btn { padding: 8px 16px; border-radius: 4px; text-decoration: none; font-size: 0.875rem; font-weight: 500; cursor: pointer; border: none; display: inline-block; } .btn-primary { background: #1a73e8; color: white; } .btn-secondary { background: #fff; color: #202124; border: 1px solid #dadce0; } .btn-success { background: #137333; color: white; padding: 4px 12px; font-size: 0.75rem; } .badge { display: inline-block; padding: 4px 12px; border-radius: 12px; font-size: 0.75rem; font-weight: 500; } .badge-warning { background: #fef7e0; color: #b06000; } .badge-success { background: #e6f4ea; color: #137333; } .badge-info { background: #e8f0fe; color: #1967d2; } .badge-danger { background: #fce8e6; color: #c5221f; }</style></head>
<body><div class="header"><h1>ðŸ“‹ Quotes & Estimates</h1><div class="header-actions"><a href="../index.php" class="btn btn-secondary">â† Back</a><a href="create-quote.php" class="btn btn-primary">+ New Quote</a></div></div><div class="container"><div class="card"><div class="card-header"><form method="GET" class="filters"><select name="status" class="filter-select" onchange="this.form.submit()"><option value="all">All Status</option><option value="draft" <?= $status == 'draft' ? 'selected' : '' ?>>Draft</option><option value="sent" <?= $status == 'sent' ? 'selected' : '' ?>>Sent</option><option value="accepted" <?= $status == 'accepted' ? 'selected' : '' ?>>Accepted</option><option value="rejected" <?= $status == 'rejected' ? 'selected' : '' ?>>Rejected</option><option value="converted" <?= $status == 'converted' ? 'selected' : '' ?>>Converted</option></select></form></div><table class="table"><thead><tr><th>Quote #</th><th>Customer</th><th>Date</th><th>Expiry</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if (empty($quotes)): ?><tr><td colspan="7" style="text-align: center; padding: 48px; color: #5f6368;"><div style="font-size: 4rem; margin-bottom: 16px;">ðŸ“‹</div><h3>No quotes found</h3><p>Create quotes to send estimates to customers.</p><a href="create-quote.php" class="btn btn-primary" style="margin-top: 16px;">+ New Quote</a></td></tr><?php else: ?><?php foreach ($quotes as $q): ?><tr><td><?= htmlspecialchars($q['quote_number']) ?></td><td><?= htmlspecialchars($q['customer_name']) ?></td><td><?= date('M d, Y', strtotime($q['date'])) ?></td><td><?= $q['expiry_date'] ? date('M d, Y', strtotime($q['expiry_date'])) : '-' ?></td><td style="font-weight: 600;">TSh <?= number_format($q['total_amount'], 2) ?></td><td><?php $statusClass = ['draft' => 'badge-warning', 'sent' => 'badge-info', 'accepted' => 'badge-success', 'rejected' => 'badge-danger', 'converted' => 'badge-success']; ?><span class="badge <?= $statusClass[$q['status']] ?? 'badge-info' ?>"><?= ucfirst($q['status']) ?></span></td><td><a href="view-quote.php?id=<?= $q['id'] ?>" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.75rem;">View</a> <?php if ($q['status'] === 'accepted' || $q['status'] === 'sent'): ?><button onclick="convertToInvoice(<?= $q['id'] ?>)" class="btn btn-success">Convert</button><?php endif; ?></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></div><script>async function convertToInvoice(id) { if (!confirm('Convert this quote to an invoice?')) return; try { const formData = new FormData(); formData.append('action', 'convert_to_invoice'); formData.append('id', id); const response = await fetch('../api/quotes.php', { method: 'POST', body: formData }); const result = await response.json(); if (result.success) { alert('Quote converted to invoice successfully!'); window.location.href = 'view-invoice.php?id=' + result.invoice_id; } else { alert('Failed: ' + result.message); } } catch (error) { alert('Error: ' + error.message); } }</script></body>
</html>

